from mindee import Client, documents

def normalize_expense(payload, config=None):
    config = config or {}
    mindee_client = Client(api_key=os.environ.get("MINDEE_API_KEY"))

    # Assuming `payload` is a file-like object.
    # For file paths, use source_from_path. For bytes, use source_from_bytes.
    input_doc = mindee_client.source_from_file(payload)

    api_response = mindee_client.parse(
        documents.TypeReceiptV5,
        input_doc,
    )

    doc = api_response.document

    if not doc:
        normalized_data = {}
    else:
        line_items = [
            {
                "description": item.description,
                "quantity": item.quantity,
                "total_amount": item.total_amount,
                "unit_price": item.unit_price,
            }
            for item in doc.line_items
        ]

        normalized_data = {
            "vendor_name": doc.supplier_name.value if doc.supplier_name else None,
            "receipt_type": doc.category.value if doc.category else None,
            "date": str(doc.date.value) if doc.date else None,
            "currency": doc.locale.currency if doc.locale else None,
            "total_amount": doc.total_amount.value if doc.total_amount else None,
            "total_tax": doc.total_tax.value if doc.total_tax else None,
            "line_items": line_items,
        }
    result = normalized_data
    return result
